```typescript
async function* paginateTweets(
  fetchFn: (userId: string, maxTweets: number, cursor: string | undefined, auth: TwitterAuth) => Promise<QueryTweetsResponse>,
  userId: string,
  maxTweets: number,
  auth: TwitterAuth
): AsyncGenerator<Tweet, void> {
  let cursor: string | undefined;
  let totalFetched = 0;

  while (totalFetched < maxTweets) {
    const response = await fetchFn(userId, maxTweets - totalFetched, cursor, auth);

    for (const tweet of response.tweets) {
      yield tweet;
      totalFetched++;
      if (totalFetched >= maxTweets) break;
    }

    cursor = response.next;
    if (!cursor) break;
  }
}

// Then simplify:
export async function* getTweetsByUserId(
  userId: string,
  maxTweets: number,
  auth: TwitterAuth,
): AsyncGenerator<Tweet, void> {
  yield* paginateTweets(fetchTweets, userId, maxTweets, auth);
}
```

