Object key order should be canonicalized to avoid false positives across runtimes/versions.


```diff
+function stableStringify(obj: unknown): string {
+  const seen = new WeakSet();
+  const stringify = (value: any): any => {
+    if (value && typeof value === 'object') {
+      if (seen.has(value)) return '[Circular]';
+      seen.add(value);
+      if (Array.isArray(value)) return value.map(stringify);
+      return Object.keys(value).sort().reduce((acc: any, k) => {
+        acc[k] = stringify(value[k]);
+        return acc;
+      }, {});
+    }
+    return value;
+  };
+  return JSON.stringify(stringify(obj));
+}
