async function generateTextWithModel(
  runtime: IAgentRuntime,
  params: GenerateTextParams,
  modelType: ModelTypeName,
  getModel: (runtime: IAgentRuntime) => string
): Promise<string> {
  const openai = createOpenAIClient(runtime);
  const modelName = getModel(runtime);
  const experimentalTelemetry = getExperimentalTelemetry(runtime);

  logger.log(`[OpenAI] Using ${modelType} model: ${modelName}`);
  logger.log(params.prompt);

  const { text: openaiResponse, usage } = await generateText({
    model: openai.languageModel(modelName),
    prompt: params.prompt,
    system: runtime.character.system ?? undefined,
    temperature: params.temperature,
    maxOutputTokens: params.maxTokens,
    frequencyPenalty: params.frequencyPenalty,
    presencePenalty: params.presencePenalty,
    stopSequences: params.stopSequences,
    experimental_telemetry: { isEnabled: experimentalTelemetry },
  });

  if (usage) {
    emitModelUsageEvent(runtime, modelType, params.prompt, usage);
  }

  return openaiResponse;
}

export async function handleTextSmall(runtime: IAgentRuntime, params: GenerateTextParams) {
  return generateTextWithModel(runtime, params, ModelType.TEXT_SMALL, getSmallModel);
}

export async function handleTextLarge(runtime: IAgentRuntime, params: GenerateTextParams) {
  return generateTextWithModel(runtime, params, ModelType.TEXT_LARGE, getLargeModel);
}
```

